using DesktopManager;

var monitors = new Monitors();
foreach (MonitorSnapshot display in monitors.GetMonitorSnapshots()) {
    Console.WriteLine($"{display.DeviceName}: {display.Width} x {display.Height}");
}

var windows = new WindowManager();
WindowInfo? editor = windows.GetWindows(processName: "notepad").FirstOrDefault();
if (editor != null) {
    windows.SnapWindow(editor, SnapPosition.Left);
}

